```tsx
// Inline mode for horizontal flows (e.g., pagination)
import { Select } from '@levain/ui-react';
import { useState } from 'react';

function InlineSelect() {
  const [pageSize, setPageSize] = useState('20');
  const options = [
    { value: "10", label: "10" },
    { value: "20", label: "20" },
    { value: "50", label: "50" }
  ];

  return (
    <div className="flex items-center gap-2">
      <Select
        id="page-size"
        label="Items per page"
        options={options}
        value={pageSize}
        onChange={(e) => setPageSize(e.target.value)}
        compact
        inline
      />
      <span className="type-body-sm">per page</span>
    </div>
  );
}
